import { Grid, Typography, Stack, Button } from "@mui/material";
import * as React from "react";
import globalSnackbar from "src/utils/snackbarUtils";
import _ from "lodash";
import HttpApiRequests from "src/utils/HttpRequests";

const HDMIOnOff: React.FC = () => {
  const sendHDMIOnOrOffMessage = (hmdiOn: boolean) => {
    let url: string = "";
    if (hmdiOn) {
      url = "/hdmi_on";
    } else {
      url = "/hdmi_off";
    }
    HttpApiRequests
      .post(url)
      .then(() => {
        globalSnackbar.success("Successfully changed HDMI state");
      })
      .catch();
  };

  return (
    <>
      <Grid
        container
        sx={{
          flexDirection: "column",
          marginY: 2,
          justifyContent: "center",
          alignItems: "center"
        }}>
        <Typography variant="h4" sx={{
          margin: 2
        }}>
          HDMI Output State
        </Typography>
        <Typography variant="body2">
          These commands allow to turn the HDMI signal on or off.
        </Typography>
        <Typography variant="body2" sx={{
          marginBottom: 2
        }}>
          This can be useful to turn on or off connected screens if they are set
          up to turn on/off with hdmi input signal.
        </Typography>
        <Stack
          direction="column"
          spacing={2}
          sx={{
            alignItems: "center",
            justifyContent: "center"
          }}>
          <Stack
            direction="row"
            spacing={2}
            sx={{
              alignItems: "center",
              justifyContent: "center"
            }}>
            <Button
              variant="contained"
              onClick={() => sendHDMIOnOrOffMessage(true)}
            >
              HDMI Signal On
            </Button>
            <Button
              variant="contained"
              onClick={() => sendHDMIOnOrOffMessage(false)}
            >
              HDMI Signal Off
            </Button>
          </Stack>
        </Stack>
      </Grid>
    </>
  );
};

export default HDMIOnOff;
